import fs from 'node:fs';
import path from 'node:path';
import {hash} from '../core/hash.js';
import {normalizeRelative} from '../core/safe-path.js';
import {CODINGVIBES_VERSION} from '../version.js';
import {PUBLIC_ROBOTS,cleanTitle,cleanDescription,absoluteUrl,jsonLdGraph,websiteSchema,breadcrumbSchema} from '../seo/metadata.js';
import {createDefaultSiteContent} from '../site/content.js';
import {contentRuntimeJs} from '../site/runtime.js';
import {kitForKind} from '../site/kits.js';
import {designModeContract,defaultDesignSystem} from '../platform/feature-suite.js';

function escHtml(s){return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');}
function titleForManifest(spec){return String(spec.request||'Build Vibe application').split(/\s+/).slice(0,8).join(' ')||'Build Vibe application';}
function pageSeoTitle(route,spec){const configured=route==='/'?spec.seo?.title:spec.seo?.pages?.[route]?.title;if(configured)return cleanTitle(configured);const site=spec.siteTemplateLabel||spec.appName||titleForManifest(spec);const raw=route==='/'?site+' | '+String(spec.siteKind||'website'):pageTitle(route)+' | '+site;return cleanTitle(raw.length>=10?raw:site+' | '+pageTitle(route));}
function pageSeoDescription(route,spec,title){const configured=route==='/'?spec.seo?.description:spec.seo?.pages?.[route]?.description;if(configured)return cleanDescription(configured);const site=spec.siteTemplateLabel||spec.appName||'this website';let raw=route==='/'?(spec.siteDescription||spec.request||('A '+String(spec.siteKind||'website')+' created with Build Vibe.')):('Explore '+title.toLowerCase()+' for '+site+'.');if(raw.length<70)raw+=' Learn more about this product, its content and capabilities on the public site.';return cleanDescription(raw);}
function seoUrl(pathname){return absoluteUrl('__SITE_URL__',pathname||'/');}
function pageSchema(route,spec,title,description){const url=seoUrl(route||'/'),siteName=spec.siteTemplateLabel||spec.appName||title;const graph=[websiteSchema('__SITE_URL__',siteName,spec.siteDescription||description,{publisher:false}),{'@type':'Organization','@id':seoUrl('/')+'#organization',name:siteName,url:seoUrl('/')},{'@type':'WebPage','@id':url+'#webpage',url,name:title,description,inLanguage:'en',isPartOf:{'@id':seoUrl('/')+'#website'},about:{'@id':seoUrl('/')+'#organization'},breadcrumb:{'@id':url+'#breadcrumb'}},breadcrumbSchema('__SITE_URL__',[{name:siteName,path:'/'},{name:title,path:route||'/'}])];return jsonLdGraph(graph);}
function pageTitle(route){if(route==='/')return 'Home';return route.slice(1).split('-').map(x=>x[0]?.toUpperCase()+x.slice(1)).join(' ');}
function navMarkup(spec){return spec.pages.filter(r=>!['/admin','/login'].includes(r)).map(r=>`<a class="nav-link" data-route="${escHtml(r)}" href="${escHtml(r)}">${escHtml(pageTitle(r))}</a>`).join('');}
function llmsTxt(spec){const publicPages=spec.pages.filter(p=>!['/admin','/login'].includes(p));const desc=pageSeoDescription('/',spec,pageSeoTitle('/',spec));return `# ${titleForManifest(spec)}\n\n> ${desc}\n\n## Public pages\n${publicPages.map(p=>'- '+p).join('\n')}\n\n## Product\n- Built with Build Vibe\n- Structured content and accessible responsive UI\n- Owner admin portal at /admin is excluded from public discovery\n`;}
function experienceMarkup(spec){
 if(!spec.experience?.threeD)return '';
 const property=spec.experience.type==='property-tour';
 return '<section class="experience-wrap card" data-reveal aria-label="'+(property?'Interactive 3D property tour':'Interactive 3D experience')+'">'+
 '<div class="experience-toolbar"><strong>'+(property?'Explore the home':'Explore in 3D')+'</strong><div class="experience-actions">'+
 '<button id="tourPlay" type="button">Camera tour</button><button id="tourRecord" type="button">Record tour</button><button id="viewLeft" type="button" aria-label="Rotate 3D view left">↶</button><button id="viewRight" type="button" aria-label="Rotate 3D view right">↷</button><button id="viewZoomOut" type="button" aria-label="Zoom out of 3D view">−</button><button id="viewZoomIn" type="button" aria-label="Zoom in to 3D view">+</button>'+
 '<label class="file-button">Load 3D model<input id="modelInput" type="file" accept=".glb,.gltf" hidden></label></div></div>'+
 '<div class="experience-stage" data-property-tour="'+(property?'true':'false')+'"><canvas id="experience3d" role="img" aria-label="Interactive 3D scene; use the view controls to navigate"></canvas>'+
 '<div id="experienceFallback" class="experience-fallback" role="status" aria-live="polite">3D is loading. Your content remains available below.</div>'+
 '<div class="hotspots" data-experience-hotspots>'+ (property?'<button type="button" data-room="Living">Living room</button><button type="button" data-room="Kitchen">Kitchen</button><button type="button" data-room="Bedroom">Bedroom</button>':'') +'</div>'+
 '</div>'+
 '<div class="tour-media"><div><h3>'+(property?'Property media':'Product & scene media')+'</h3><p class="muted">'+(property?'Add reference images and a walkthrough video.':'Attach reference images and an MP4/WebM video to enrich this 3D experience.')+'</p><label class="file-button" for="experienceImageInput">Load image</label><input id="experienceImageInput" type="file" accept="image/png,image/jpeg,image/webp,image/avif,image/gif" aria-label="Upload 3D experience image"><label class="file-button" for="videoInput">Load video</label><input id="videoInput" type="file" accept="video/mp4,video/webm" aria-label="Upload 3D experience video"></div><div class="experience-media-preview"><img id="experienceImage" alt="Uploaded image preview for this 3D experience" hidden><video id="tourVideo" controls playsinline preload="metadata" hidden></video></div></div>'+
 '</section><script type="module" src="/experience.js"></script>';
}
function contentSections(spec){
 const kind=spec.siteKind||spec.contentModel?.kit||'business';
 const sec=(title,source,copy='')=>`<section class="card content-section" data-reveal><div class="section-heading"><div><span class="eyebrow">${escHtml(kind)}</span><h2>${escHtml(title)}</h2>${copy?`<p class="muted">${escHtml(copy)}</p>`:''}</div></div><div data-content-grid="${escHtml(source)}" class="content-grid"></div></section>`;
 if(kind==='ecommerce')return `<section class="store-hero card"><div><span class="eyebrow">Storefront</span><h2><span data-brand-name>Your brand</span>, built around your catalog</h2><p class="lead-small">Products, variants, inventory and collections live in editable content instead of being trapped in the page markup.</p><div class="store-actions"><a class="primary-link" href="/shop">Shop collection</a><span class="cart-chip">Cart <strong data-cart-count>0</strong></span></div></div><div class="store-hero-orb" aria-hidden="true"></div></section><section class="card content-section"><div class="section-heading"><div><span class="eyebrow">Catalog</span><h2>Products</h2><p class="muted">Search and filter the live content catalog.</p></div><div class="catalog-tools"><input data-product-search placeholder="Search products…" aria-label="Search products"><select data-product-category aria-label="Filter product category"><option value="">All categories</option></select></div></div><div data-product-grid class="product-grid"></div><div data-cart-feedback class="muted small cart-feedback" aria-live="polite"></div></section>${sec('Featured collections','collections','Collections stay independent from the visual template so the same catalog can power multiple sections and pages.')}`;
 if(kind==='marketplace')return `${sec('Marketplace products','products','Keep vendor and product data separate so filters, cards and seller stories can evolve independently.')}${sec('Featured vendors','vendors','Vendor records are editable without touching product presentation.')}`;
 if(kind==='portfolio'||kind==='agency')return `${sec('Selected work','portfolio','Case studies and projects are data records, not hardcoded cards.')}${sec('Services','services')}${sec('Team','team')}${sec('Testimonials','testimonials')}`;
 if(kind==='hospitality')return `${sec('Rooms & stays','rooms','Room content can be updated without rebuilding the visual theme.')}${sec('Menu','products','Menu items use the same structured commerce record model.')}${sec('Experiences','services')}`;
 if(kind==='realEstate')return `${sec('Available properties','properties','Listings, facts and media are structured content; the 3D experience sits alongside them.')}`;
 if(kind==='education')return `${sec('Courses','courses','Course records remain editable independently from the academy theme.')}${sec('Instructors','instructors')}`;
 if(kind==='content')return `${sec('Latest stories','posts','Publish, reorder or replace stories without rebuilding the page.')}${sec('Authors','authors')}`;
 if(kind==='event')return `${sec('Upcoming events','events')}${sec('Speakers','speakers')}${sec('Sponsors','sponsors')}`;
 if(kind==='immersive')return sec('Immersive scenes','scenes','Scene records can reference 3D assets, camera paths and motion settings.');
 if(kind==='local')return `${sec('Services','services','Service cards, service areas and reviews are editable records.')}${sec('Reviews','testimonials')}`;
 return `${sec('Services','services','Start with structured service content, then ask the agent to transform the presentation.')}${sec('Testimonials','testimonials')}${sec('Team','team')}`;
}
function pageMarkup(route,spec){
 const title=pageSeoTitle(route,spec);
 const description=pageSeoDescription(route,spec,title);
 const canonicalPath=route||'/';
 const seoAbsolute=seoUrl(canonicalPath);
 const schema=pageSchema(route,spec,title,description);

 const apis=spec.apis.filter(a=>a.path.includes(route.slice(1))||route==='/');
 const pills=spec.components.slice(0,6).map(c=>`<span class="pill">${escHtml(c)}</span>`).join('');
 const immersive=spec.experience?.threeD?experienceMarkup(spec):'';
 const content=route==='/'?contentSections(spec):(['ecommerce','marketplace'].includes(spec.siteKind)&&route==='/shop'?contentSections(spec):'');
 const legacyImmersive=spec.styling?.visual?.threeD&&!spec.experience?.threeD?`<section class="forest-scene" aria-label="3D forest storefront"><div class="tree tree-a"><div class="branch"></div><div class="product-orb">${escHtml(spec.dataModel.find(x=>x.name==='products')?'Product':'Item')}</div></div><div class="tree tree-b"><div class="branch"></div><div class="product-orb">Store</div></div><div class="mist"></div></section>`:'';
 const checkout=spec.behavior?.payments?`<section class="card checkout" data-reveal><h2>Secure checkout</h2><p>Checkout is server-mediated; card details must be collected by the configured payment provider rather than stored by this app.</p><button data-checkout="true">Start secure checkout</button><pre data-checkout-result></pre></section>`:'';
 const apiBlock=apis.length?`<section class="card" data-reveal><h2>Live capabilities</h2>${apis.map(a=>`<div class="api-row"><code>${escHtml(a.method)} ${escHtml(a.path)}</code><button data-api="${escHtml(a.path)}" data-method="${escHtml(a.method)}">Test</button></div>`).join('')}<pre data-result></pre></section>`:'';
 const form=spec.behavior.search?`<section class="card" data-reveal><h2>Search</h2><input id="search" placeholder="Search this experience…" aria-label="Search this experience"><div id="searchResult" class="muted">Type to filter the generated feature cards.</div></section>`:'';
 const contact=route==='/contact'?`<section class="card conversion-panel" data-reveal><span class="eyebrow">Contact</span><h2>Tell us what you need</h2><p class="muted">Use this form to start a conversation. The generated endpoint stores submissions locally until a production delivery provider is connected.</p><form id="contactForm"><label>Name<input name="name" autocomplete="name" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Message<textarea name="message" rows="6" required></textarea></label><button type="submit">Send message</button><p id="contactResult" class="muted" aria-live="polite"></p></form></section>`:'';
 const legal=route==='/privacy'?`<section class="card legal-copy" data-reveal><span class="eyebrow">Privacy</span><h2>Privacy at a glance</h2><p>Explain what information this product collects, why it is used, retention, cookies, analytics and how customers can request access or deletion.</p><h3>Data minimization</h3><p>Only collect information required for the requested product experience and configure production providers before launch.</p></section>`:route==='/terms'?`<section class="card legal-copy" data-reveal><span class="eyebrow">Terms</span><h2>Terms of service</h2><p>Replace this launch-ready outline with your final legal terms, business identity, payment terms, acceptable-use rules and support policy before publishing.</p><h3>Service terms</h3><p>Product behavior, pricing, refunds and third-party services should be stated clearly and kept consistent with the configured production providers.</p></section>`:'';
 const about=route==='/about'?`<section class="card story-panel" data-reveal><span class="eyebrow">About</span><h2>Built around your story</h2><p>This page is automatically included when a customer-facing site needs a trust-building company or creator story. Replace the sample copy with your real positioning, proof and team details.</p></section>`:'';
 const footer=`<footer class="site-footer"><div><strong>${escHtml(spec.siteTemplateLabel||spec.appName||titleForManifest(spec))}</strong><span>Built with Build Vibe</span></div><nav aria-label="Footer"><a href="/contact">Contact</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></nav></footer>`;
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1020"><meta name="application-name" content="${escHtml(title)}"><meta name="author" content="${escHtml(spec.siteTemplateLabel||spec.appName||title)}"><meta name="description" content="${escHtml(description)}"><meta name="robots" content="${PUBLIC_ROBOTS}"><link rel="icon" href="/favicon.svg"><link rel="manifest" href="/manifest.webmanifest"><link rel="canonical" href="${escHtml(seoAbsolute)}"><meta property="og:type" content="website"><meta property="og:title" content="${escHtml(title)}"><meta property="og:description" content="${escHtml(description)}"><meta property="og:url" content="${escHtml(seoAbsolute)}"><meta property="og:site_name" content="${escHtml(spec.siteTemplateLabel||spec.appName||title)}"><meta property="og:locale" content="en_US"><meta property="og:image" content="${seoUrl('/og-default.svg')}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:type" content="image/svg+xml"><meta property="og:image:alt" content="${escHtml(title)} preview"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${escHtml(title)}"><meta name="twitter:description" content="${escHtml(description)}"><meta name="twitter:image" content="${seoUrl('/og-default.svg')}"><meta name="twitter:image:alt" content="${escHtml(title)} preview"><script type="application/ld+json">${schema}</script><title>${escHtml(title)}</title><link rel="stylesheet" href="/styles.css"></head><body data-kind="${escHtml(spec.siteKind||"business")}" data-style="${escHtml(spec.styling?.visual?.style||"modern")}" data-motion="${escHtml(spec.styling?.designSystem?.motion?.mode||"smooth")}"><header class="nav"><div class="nav-inner"><a class="brand" href="/"><span data-brand-name>Build Vibe app</span></a><nav data-nav>${navMarkup(spec)}</nav><span class="cart-chip">Cart <strong data-cart-count>0</strong></span></div></header><main class="container motion-page"><nav class="breadcrumb" aria-label="Breadcrumb" data-reveal><a href="/">Home</a><span aria-hidden="true">/</span><span>${escHtml(title)}</span></nav><div class="eyebrow" data-reveal>Verified generated application</div><h1 data-reveal>${escHtml(title)}</h1><p class="lead" data-reveal>${escHtml(route==='/'?spec.request:`A generated ${pageTitle(route).toLowerCase()} experience.`)}</p><div class="pills">${pills}</div><section class="hero-grid" data-reveal><div class="card"><h2>Designed from your requirements</h2><p>Pages, APIs, behavior, data entities and visual direction come from the application contract.</p><div class="metric"><strong>${spec.pages.length}</strong><span>pages</span><strong>${spec.apis.length}</strong><span>APIs</span><strong>${spec.dataModel.length}</strong><span>entities</span></div></div><div class="card accent"><h2>Content stays editable</h2><p>Your ${escHtml(kitForKind(spec.siteKind||'business').label)} content is stored separately from the visual layer. Add, update, delete or reorder records without replacing the theme.</p><span class="verified">Content-driven site kit</span></div></div>${content}${immersive}${legacyImmersive}${checkout}${apiBlock}${form}${contact}${legal}${about}</main>${footer}<script src="/app.js"></script><script src="/motion.js"></script><script type="module" src="/content-runtime.js"></script></body></html>`;
}
function styles(){return `:root{--motion-duration-fast:180ms;--motion-duration-base:420ms;--motion-duration-slow:760ms;--motion-duration-scene:1200ms;--motion-ease:cubic-bezier(.22,1,.36,1);--motion-enter:cubic-bezier(.16,1,.3,1);--motion-distance:24px;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;color:#e6edf3;background:#0b1020;line-height:1.6}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at top,#182341,#0b1020 55%);min-height:100vh}.motion-page{perspective:1200px}.motion-page [data-reveal]{opacity:0;transform:translate3d(0,var(--motion-distance),0);transition:opacity var(--motion-duration-slow) var(--motion-enter),transform var(--motion-duration-slow) var(--motion-ease);transition-delay:var(--motion-delay,0ms)}.motion-page [data-reveal].is-visible{opacity:1;transform:none}.card{transition:transform var(--motion-duration-base) var(--motion-ease),border-color var(--motion-duration-base) var(--motion-ease),box-shadow var(--motion-duration-base) var(--motion-ease)}.card:hover{transform:translate3d(0,-4px,0);border-color:#3c5279;box-shadow:0 28px 80px #0004}.nav{position:sticky;top:0;z-index:2;background:#0b1020e8;border-bottom:1px solid #23304d;backdrop-filter:blur(10px)}.nav-inner{max-width:1100px;margin:auto;padding:16px 22px;display:flex;gap:20px;align-items:center;justify-content:space-between}.brand{font-weight:800;text-decoration:none;color:#fff}.nav nav{display:flex;gap:8px;flex-wrap:wrap}.nav-link{color:#aebbd1;text-decoration:none;padding:7px 10px;border-radius:10px}.nav-link:hover{background:#17223a;color:#fff}.container{max-width:1100px;margin:0 auto;padding:64px 22px 100px}.eyebrow{text-transform:uppercase;letter-spacing:.18em;font-size:12px;color:#83a4ff}.lead{font-size:20px;color:#aebbd1;max-width:760px}.pills{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.pill,.verified{padding:6px 10px;border-radius:999px;background:#182540;color:#c8d5ee;border:1px solid #29385b;font-size:12px}.hero-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{border:1px solid #253352;background:#11192cdd;border-radius:20px;padding:22px;box-shadow:0 20px 60px #0002;margin-top:18px}.accent{background:linear-gradient(160deg,#17233b,#11192c)}h1{font-size:clamp(40px,7vw,76px);line-height:1.02;margin:14px 0}h2{margin-top:0}.metric{display:flex;align-items:end;gap:10px;flex-wrap:wrap}.metric strong{font-size:32px}.metric span{color:#91a0ba;margin-right:20px}.forest-scene{position:relative;min-height:420px;margin:28px 0;border-radius:28px;overflow:hidden;perspective:1000px;background:radial-gradient(circle at 50% 10%,#315b42,#0b2419 55%,#07130d);border:1px solid #2d6147}.forest-scene:before,.forest-scene:after{content:'';position:absolute;inset:auto 0 0;height:42%;background:linear-gradient(180deg,transparent,#06120c)}.tree{position:absolute;bottom:-30px;width:180px;height:330px;transform-style:preserve-3d}.tree:before{content:'';position:absolute;left:74px;bottom:0;width:32px;height:260px;border-radius:18px;background:linear-gradient(90deg,#3d2415,#8a5b2d,#2b180d);transform:rotateX(5deg) translateZ(30px)}.tree:after{content:'';position:absolute;left:0;bottom:210px;width:180px;height:120px;border-radius:50%;background:radial-gradient(circle,#356b43 0 38%,#1e492d 60%,transparent 70%);filter:drop-shadow(0 25px 25px #0008)}.tree-a{left:8%;transform:rotateY(12deg) rotateX(2deg)}.tree-b{right:8%;transform:rotateY(-12deg) rotateX(2deg) scale(.9)}.branch{position:absolute;left:55px;bottom:185px;width:120px;height:16px;background:#5a351b;border-radius:20px;transform:rotate(-20deg) translateZ(55px);z-index:3}.product-orb{position:absolute;left:88px;bottom:120px;z-index:5;padding:16px 20px;border-radius:18px;background:#d9f7e2;color:#082015;font-weight:800;box-shadow:0 20px 50px #0008;transform:translateZ(100px) rotateY(-8deg)}.mist{position:absolute;inset:0;background:radial-gradient(circle at 30% 60%,#b5f1c522,transparent 25%),radial-gradient(circle at 70% 40%,#9de7ff16,transparent 30%);pointer-events:none}.checkout button{border:0;border-radius:12px;padding:12px 16px;background:#d9f7e2;color:#082015;font-weight:800;cursor:pointer}.api-row{display:flex;align-items:center;justify-content:space-between;padding:10px 0;border-bottom:1px solid #263451}.api-row button{border:1px solid #38507f;background:#17233b;color:#e9f0ff;border-radius:10px;padding:7px 12px;cursor:pointer}input{width:100%;padding:12px 14px;border-radius:12px;border:1px solid #30415f;background:#0c1426;color:#fff}pre{white-space:pre-wrap;background:#09101e;border-radius:12px;padding:12px;color:#a9c6ff;min-height:40px}.experience-wrap{overflow:hidden}.experience-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.experience-actions{display:flex;gap:6px;flex-wrap:wrap}.experience-actions button,.file-button{border:1px solid #314564;background:#142039;color:#e8efff;border-radius:9px;padding:7px 10px;font-size:11px;cursor:pointer}.experience-stage{position:relative;height:min(68vh,560px);min-height:360px;margin-top:12px;border:1px solid #253756;border-radius:18px;overflow:hidden;background:radial-gradient(circle at 45% 15%,#264b5f,#0a1518 62%,#050a09)}#experience3d{display:block;width:100%;height:100%}.experience-fallback{position:absolute;left:12px;bottom:12px;padding:7px 9px;border-radius:8px;background:#07111ccc;color:#a8bdd5;font-size:11px}.hotspots{position:absolute;left:12px;top:12px;display:flex;gap:6px;flex-wrap:wrap}.hotspots button{border:1px solid #395176;background:#08111dcc;color:#edf4ff;border-radius:999px;padding:7px 9px;font-size:10px;cursor:pointer}.tour-media{display:grid;grid-template-columns:1fr 1.2fr;gap:14px;margin-top:12px;align-items:start}.tour-media input{margin-top:6px}.tour-media .experience-media-preview{display:grid;gap:10px;min-width:0}.tour-media img{width:100%;max-height:360px;object-fit:contain;border-radius:12px;border:1px solid #253756;background:#05080c}.tour-media img[hidden],.tour-media video[hidden]{display:none}.tour-media video{width:100%;min-height:180px;border-radius:12px;border:1px solid #253756;background:#05080c}.download-link{display:inline-block;margin-top:8px;color:#b9cfff}.experience-wrap .muted{color:#91a2bb}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.motion-page [data-reveal],.motion-page [data-reveal].is-visible{opacity:1;transform:none;transition:none}.card,.card:hover{transform:none;transition:none}}@media(max-width:760px){.experience-stage{min-height:280px;height:52vh}.tour-media{grid-template-columns:1fr}}@media(max-width:760px){.hero-grid{grid-template-columns:1fr}.nav-inner{align-items:flex-start;flex-direction:column}}.section-heading{display:flex;justify-content:space-between;align-items:end;gap:18px;flex-wrap:wrap}.content-section{overflow:hidden}.content-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.content-card,.product-card{border:1px solid #243451;background:#0b1423;border-radius:16px;overflow:hidden}.content-media,.product-media{min-height:140px;background:linear-gradient(140deg,#16243e,#0a111c);display:block}.content-media img,.product-media img{display:block;width:100%;height:170px;object-fit:cover}.content-card>div:last-child{padding:14px}.content-kicker,.product-kicker{display:block;text-transform:uppercase;letter-spacing:.12em;color:#7284a6;font-size:9px}.content-card h3,.product-body h3{margin:5px 0 6px;font-size:16px}.content-card p,.product-body p{margin:0;color:#8fa0ba;font-size:11px}.product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.product-body{padding:12px}.product-media{position:relative;text-decoration:none}.product-badge{position:absolute;left:8px;top:8px;padding:4px 7px;border-radius:999px;background:#08111dcc;color:#d9e5f9;font-size:9px}.product-foot{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:12px}.product-foot strong{font-size:15px}.product-foot button,.primary-link{border:0;border-radius:9px;padding:8px 10px;background:#d9f7e2;color:#082015;font-weight:800;text-decoration:none;cursor:pointer;font-size:10px}.store-hero{display:grid;grid-template-columns:1.2fr .8fr;gap:16px;align-items:center;margin-top:18px}.lead-small{max-width:600px;color:#91a2bb}.store-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:14px}.store-hero-orb{min-height:210px;border-radius:22px;background:radial-gradient(circle at 40% 35%,#d9f7e244,transparent 30%),radial-gradient(circle at 60% 60%,#7d8dff66,transparent 35%),linear-gradient(145deg,#17243a,#0a101b);box-shadow:inset 0 0 90px #0008,0 30px 90px #0005}.catalog-tools{display:flex;gap:6px;min-width:min(100%,440px)}.catalog-tools input,.catalog-tools select{min-width:0;flex:1;padding:9px 10px;border-radius:9px;border:1px solid #30415f;background:#0c1426;color:#fff}.empty-state{padding:22px;border:1px dashed #324565;border-radius:12px;color:#8c9ab1}.cart-feedback{margin-top:10px}.cart-chip{display:inline-flex;align-items:center;gap:5px;border:1px solid #2a3c5f;background:#10192b;border-radius:999px;padding:5px 8px;color:#cdd9ed;font-size:10px}@media(max-width:900px){.product-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.content-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.store-hero{grid-template-columns:1fr}}@media(max-width:560px){.product-grid,.content-grid{grid-template-columns:1fr}.catalog-tools{width:100%;flex-direction:column}.store-hero-orb{min-height:150px}}

.site-footer{max-width:1100px;margin:0 auto;padding:32px 22px 56px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;color:#8f9db5;border-top:1px solid #263451}.site-footer div{display:flex;gap:12px;flex-direction:column}.site-footer nav{display:flex;gap:16px}.site-footer a{color:inherit;text-decoration:none}.site-footer a:hover{text-decoration:underline}.conversion-panel form{display:grid;gap:14px}.conversion-panel label{display:grid;gap:7px;font-weight:700}.conversion-panel textarea{width:100%;padding:12px 14px;border-radius:12px;border:1px solid #30415f;background:#0c1426;color:#fff;resize:vertical}.conversion-panel button{justify-self:start;border:0;border-radius:12px;padding:12px 18px;background:#8ea8ff;color:#08111c;font-weight:800;cursor:pointer}.legal-copy,.story-panel{max-width:820px}.site-footer{position:relative}.site-footer strong{color:#fff}
[data-style="luxury"]{font-family:Georgia,ui-serif,serif;background:radial-gradient(circle at 75% 0%,#332614,#0b1020 52%)}
[data-style="editorial"]{font-family:Georgia,ui-serif,serif;background:linear-gradient(145deg,#17130f,#0b1020 58%)}
[data-style="minimal"]{background:#0d1117}
[data-style="brutalist"]{background:#f2f0e8;color:#111}
[data-style="brutalist"] .card{background:#fff;color:#111;border:3px solid #111;border-radius:4px;box-shadow:8px 8px 0 #111}
[data-style="brutalist"] .muted{color:#4a4a4a}
[data-style="playful"] .card{border-radius:28px}
[data-style="glass"] .card{background:#ffffff12;backdrop-filter:blur(18px);border-color:#ffffff24}
.motion-item{opacity:0;transform:translate3d(0,var(--motion-distance,24px),0) scale(.985);filter:saturate(.96);transition:opacity var(--motion-duration,650ms) var(--motion-ease,cubic-bezier(.16,1,.3,1)),transform var(--motion-duration,650ms) var(--motion-ease,cubic-bezier(.16,1,.3,1)),filter var(--motion-duration,650ms) var(--motion-ease,cubic-bezier(.16,1,.3,1));transition-delay:calc(var(--motion-index,0) * var(--motion-stagger,55ms))}
.motion-visible{opacity:1;transform:none;filter:none}
.motion-item.motion-visible:hover{transform:translate3d(var(--mx,0),calc(-3px + var(--my,0)),0)}
.motion-scene{transform:translateZ(0);will-change:transform;animation:cvSceneFloat 12s ease-in-out infinite}
.motion-product{opacity:0;transform:translate3d(0,18px,0) scale(.98);transition:opacity 560ms var(--motion-ease),transform 560ms var(--motion-ease);transition-delay:calc(var(--motion-index,0) * 45ms)}
.motion-product.motion-visible{opacity:1;transform:none}
.motion-image-reveal,.motion-image-soft{transition:transform 900ms cubic-bezier(.16,1,.3,1),filter 700ms ease;will-change:transform}
.motion-image-reveal{clip-path:inset(0 0 100% 0);transform:scale(1.04)}
.motion-visible .motion-image-reveal{clip-path:inset(0);transform:scale(1)}
.motion-image-soft{transform:scale(1.025);filter:saturate(.9)}
.motion-visible .motion-image-soft{transform:scale(1);filter:none}
.hero-grid .card:first-child{position:relative;overflow:hidden}
.hero-grid .card:first-child:after{content:"";position:absolute;inset:-35% auto auto -12%;width:260px;height:260px;border-radius:50%;background:radial-gradient(circle,#8ea8ff24,transparent 68%);animation:cvGlowDrift 9s ease-in-out infinite;pointer-events:none}
.store-hero-orb{animation:cvOrbFloat 9s ease-in-out infinite}
[data-motion="cinematic"] .store-hero-orb,[data-motion="luxury"] .store-hero-orb{animation-duration:12s}
[data-motion="playful"] .card.motion-item.motion-visible{animation:cvSpringIn 560ms cubic-bezier(.34,1.56,.64,1) both}
[data-motion="snappy"] .motion-item{transition-duration:420ms}
@keyframes cvSceneFloat{0%,100%{transform:translate3d(0,0,0)}50%{transform:translate3d(0,-6px,0)}}
@keyframes cvOrbFloat{0%,100%{transform:translate3d(0,0,0) scale(1)}50%{transform:translate3d(0,-8px,0) scale(1.015)}}
@keyframes cvGlowDrift{0%,100%{transform:translate3d(0,0,0)}50%{transform:translate3d(42px,18px,0)}}
@keyframes cvSpringIn{0%{opacity:0;transform:translateY(18px) scale(.96)}100%{opacity:1;transform:translateY(0) scale(1)}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.motion-item,.motion-product{opacity:1!important;transform:none!important;filter:none!important;transition:none!important;animation:none!important}.motion-scene,.store-hero-orb,.hero-grid .card:first-child:after{animation:none!important}.motion-image-reveal,.motion-image-soft{clip-path:none!important;transform:none!important;filter:none!important}}
`;}
function appJs(spec){return `const result=document.querySelector('[data-result]');document.querySelectorAll('[data-api]').forEach(btn=>btn.addEventListener('click',async()=>{const method=btn.dataset.method||'GET';const init={method,headers:{'content-type':'application/json'}};if(!['GET','HEAD'].includes(method))init.body=JSON.stringify({demo:true});try{const r=await fetch(btn.dataset.api,init);const j=await r.json();if(result)result.textContent=JSON.stringify(j,null,2)}catch(e){if(result)result.textContent=e.message}}));const search=document.querySelector('#search');if(search)search.addEventListener('input',()=>{document.querySelector('#searchResult').textContent=search.value?\`Filtering generated capabilities for “\${search.value}”…\`:'Type to filter the generated feature cards.'});document.querySelector('[data-checkout]')?.addEventListener('click',async()=>{const out=document.querySelector('[data-checkout-result]');try{const r=await fetch('/api/checkout/session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({cart:[{productId:'demo',quantity:1}]})});const j=await r.json();if(out)out.textContent=JSON.stringify(j,null,2)}catch(e){if(out)out.textContent=e.message}});window.addEventListener('error',e=>console.error(e.error||e.message));document.querySelector('#contactForm')?.addEventListener('submit',async e=>{e.preventDefault();const out=document.querySelector('#contactResult');const body=Object.fromEntries(new FormData(e.currentTarget).entries());try{const r=await fetch('/api/contact',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(out)out.textContent=r.ok?'Thanks — your message was received.':(j.error||'Unable to send message.');if(r.ok)e.currentTarget.reset()}catch(error){if(out)out.textContent=error.message}});${spec.target?.id==='web-pwa' ? "if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});" : ''}`}
function routesJs(spec){return `export const routes=${JSON.stringify(spec.pages)};\nexport const apiRoutes=${JSON.stringify(spec.apis)};\nexport const routeMeta=${JSON.stringify(Object.fromEntries(spec.pages.map(p=>[p,{title:pageTitle(p)}])))};\n`;}
function modelJs(spec){return `export const dataModel=${JSON.stringify(spec.dataModel,null,2)};\nexport const behavior=${JSON.stringify(spec.behavior,null,2)};\n`;}
function serverJs(spec){const publicLogin=Boolean(spec.behavior?.publicLogin);return `import{createServer}from'node:http';import fs from'node:fs';import {createSession,readSession,cookieHeader,verifyOwnerPassword,beginGoogleAuth,completeGoogleAuth,googleConfigured,isOwnerEmail} from './auth.js';import path from'node:path';import{fileURLToPath}from'node:url';\nconst root=path.dirname(fileURLToPath(import.meta.url));const publicDir=path.join(root,'..','public');const spec=JSON.parse(fs.readFileSync(path.join(root,'..','codingvibes.app.json'),'utf8'));const port=Number(process.env.PORT||4300);\nconst stateDir=path.join(root,'..','.data');const stateFile=path.join(stateDir,'records.json');let stores=new Map();function loadStores(){try{const raw=JSON.parse(fs.readFileSync(stateFile,'utf8'));stores=new Map(Object.entries(raw));}catch{stores=new Map(${JSON.stringify(spec.dataModel.map(x=>[x.name,[]]))});}}function saveStores(){fs.mkdirSync(stateDir,{recursive:true});const tmp=stateFile+'.tmp';fs.writeFileSync(tmp,JSON.stringify(Object.fromEntries(stores),null,2)+'\\n','utf8');fs.renameSync(tmp,stateFile)}loadStores();const mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.webp':'image/webp','.mp4':'video/mp4','.webm':'video/webm'};const contentFile=path.join(publicDir,'content','site.json');const fallbackContent={version:'1.0',kit:spec.siteKind||'business',templateId:spec.siteTemplateId||'',templateLabel:spec.siteTemplateLabel||'',brand:{name:'Your brand',tagline:'Built with Build Vibe'},seo:{title:'',description:'',image:'',canonical:''},services:[{id:'service-default',title:'Featured service',description:'Describe your primary service here.',status:'active'}]};const readContent=()=>{try{const value=JSON.parse(fs.readFileSync(contentFile,'utf8'));return value&&typeof value==='object'?{...fallbackContent,...value}:{...fallbackContent}}catch{return {...fallbackContent}}};const writeContent=value=>{fs.mkdirSync(path.dirname(contentFile),{recursive:true});const tmp=contentFile+'.tmp';fs.writeFileSync(tmp,JSON.stringify(value,null,2)+'\\n','utf8');fs.renameSync(tmp,contentFile)};const owner=(req)=>{const s=readSession(req);return s&&isOwnerEmail(s.email)?s:null};\nconst seed=new Map([['health',[{id:'health',status:'ok'}]]]);\nfunction send(res,status,type,body){res.writeHead(status,{'content-type':type,'cache-control':'no-store'});res.end(body)}\nfunction publicBase(req){const proto=String(req.headers['x-forwarded-proto']||'http').split(',')[0].trim()||'http';const host=String(req.headers['x-forwarded-host']||req.headers.host||'localhost').split(',')[0].trim();const base=String(process.env.CV_PUBLIC_URL||proto+'://'+host).trim();return base.endsWith('/')?base.slice(0,-1):base}\nfunction xmlEscape(value){return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}\nfunction htmlAttr(value){return String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}
function applyContentSeo(html,req,route,content){const base=publicBase(req),seo=content?.seo&&typeof content.seo==='object'?content.seo:{},brand=String(content?.brand?.name||spec.siteTemplateLabel||spec.appName||'Website').trim();const currentTitle=html.match(/<title>([^<]+)<\\/title>/i)?.[1]||brand+' | '+String(spec.siteKind||'website');const currentDescription=html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i)?.[1]||('Explore '+brand+' and its public content.');let title=String(seo.title||currentTitle).replace(/\\s+/g,' ').trim();if(title.length<10)title=brand+' | '+String(spec.siteKind||'website');title=title.slice(0,60);let description=String(seo.description||currentDescription).replace(/\\s+/g,' ').trim();if(description.length<70)description+=' Learn more about this product, its content and capabilities on the public site.';description=description.slice(0,160);const canonicalValue=String(seo.canonical||base+(route||'/')).trim();const canonical=canonicalValue.startsWith('/')?base+canonicalValue:canonicalValue;const imageValue=String(seo.image||base+'/og-default.svg').trim();const image=imageValue.startsWith('/')?base+imageValue:imageValue;const repl=(source,re,tag)=>source.replace(re,tag);let out=html;out=out.replace(/<title>[^<]*<\\/title>/i,'<title>'+htmlAttr(title)+'</title>');out=repl(out,/<meta[^>]+name=["']description["'][^>]*>/i,'<meta name="description" content="'+htmlAttr(description)+'">');out=repl(out,/<link[^>]+rel=["']canonical["'][^>]*>/i,'<link rel="canonical" href="'+htmlAttr(canonical)+'">');out=repl(out,/<meta[^>]+property=["']og:title["'][^>]*>/i,'<meta property="og:title" content="'+htmlAttr(title)+'">');out=repl(out,/<meta[^>]+property=["']og:description["'][^>]*>/i,'<meta property="og:description" content="'+htmlAttr(description)+'">');out=repl(out,/<meta[^>]+property=["']og:url["'][^>]*>/i,'<meta property="og:url" content="'+htmlAttr(canonical)+'">');out=repl(out,/<meta[^>]+property=["']og:site_name["'][^>]*>/i,'<meta property="og:site_name" content="'+htmlAttr(brand)+'">');out=repl(out,/<meta[^>]+property=["']og:image["'][^>]*>/i,'<meta property="og:image" content="'+htmlAttr(image)+'">');out=repl(out,/<meta[^>]+name=["']twitter:title["'][^>]*>/i,'<meta name="twitter:title" content="'+htmlAttr(title)+'">');out=repl(out,/<meta[^>]+name=["']twitter:description["'][^>]*>/i,'<meta name="twitter:description" content="'+htmlAttr(description)+'">');out=repl(out,/<meta[^>]+name=["']twitter:image["'][^>]*>/i,'<meta name="twitter:image" content="'+htmlAttr(image)+'">');return out}
function renderHtml(file,req,route='/'){let html=fs.readFileSync(file,'utf8').replaceAll('__SITE_URL__',publicBase(req));if(route!=='/admin'&&route!=='/login')html=applyContentSeo(html,req,route,readContent());return html}\nfunction staticFile(pathname){const relative=decodeURIComponent(pathname).split('/').filter(Boolean).join('/');const file=path.resolve(publicDir,relative);const rootPath=path.resolve(publicDir);if(!(file===rootPath||file.startsWith(rootPath+path.sep))||!fs.existsSync(file)||!fs.statSync(file).isFile())return null;return file;}\nfunction readBody(req){return new Promise((resolve,reject)=>{let s='';req.on('data',c=>{s+=c;if(s.length>1_000_000){reject(new Error('body too large'));req.destroy()}});req.on('end',()=>{try{resolve(s?JSON.parse(s):{})}catch{resolve({})}});req.on('error',reject)})}\ncreateServer(async(req,res)=>{try{const u=new URL(req.url||'/',\`http://\${req.headers.host||'localhost'}\`);if(u.pathname==='/api/health')return send(res,200,mime['.json'],JSON.stringify({ok:true,app:spec.appType,version:spec.version,requestHash:spec.id}));if(u.pathname==='/admin'){const f=path.join(publicDir,'admin.html');return send(res,200,mime['.html'],fs.readFileSync(f))}
if(u.pathname==='/login'){const f=path.join(publicDir,'login.html');if(fs.existsSync(f))return send(res,200,mime['.html'],fs.readFileSync(f))}
if(u.pathname==='/auth/google'){try{res.writeHead(302,{location:beginGoogleAuth({admin:u.searchParams.get('admin')==='1'})});res.end();return}catch(e){res.writeHead(503,{location:'/admin?error='+encodeURIComponent(e.message)});res.end();return}}
if(u.pathname==='/auth/google/callback'){try{const result=await completeGoogleAuth(u.searchParams.get('code'),u.searchParams.get('state'));res.writeHead(302,{location:result.admin?'/admin':'/','set-cookie':cookieHeader(createSession(result.email,result.owner?'owner':'user'))});res.end();return}catch(e){res.writeHead(403,{location:'/admin?error='+encodeURIComponent(e.message)});res.end();return}}
if(u.pathname==='/api/auth/admin-login'&&req.method==='POST'){const body=await readBody(req);if(!verifyOwnerPassword(body.email,body.password))return send(res,401,mime['.json'],JSON.stringify({ok:false,error:'invalid_owner_credentials'}));res.writeHead(200,{'content-type':mime['.json'],'set-cookie':cookieHeader(createSession(body.email,'owner'))});res.end(JSON.stringify({ok:true,role:'owner'}));return}
if(u.pathname==='/api/auth/session'&&req.method==='GET'){const session=readSession(req);return send(res,200,mime['.json'],JSON.stringify({ok:true,authenticated:Boolean(session),email:session?.email||null}));}
if(u.pathname==='/api/auth/logout'&&req.method==='POST'){res.writeHead(200,{'content-type':mime['.json'],'set-cookie':cookieHeader('',0)});res.end(JSON.stringify({ok:true}));return}
if(u.pathname==='/api/admin/session'&&req.method==='GET'){const session=readSession(req);return send(res,200,mime['.json'],JSON.stringify({ok:true,authenticated:Boolean(session),owner:Boolean(session&&isOwnerEmail(session.email)),email:session?.email||null,ownerConfigured:Boolean(process.env.CV_OWNER_EMAIL||process.env.CV_GOOGLE_OWNER_EMAILS),googleConfigured:googleConfigured()}))}
if(u.pathname==='/api/admin/overview'&&req.method==='GET'){if(!owner(req))return send(res,401,mime['.json'],JSON.stringify({ok:false,error:'owner_authentication_required'}));const content=readContent(),counts=Object.fromEntries(Object.entries(content).filter(([k,v])=>Array.isArray(v)).map(([k,v])=>[k,v.length]));return send(res,200,mime['.json'],JSON.stringify({ok:true,site:content.brand||{},counts}));}
if(u.pathname==='/api/admin/content'&&req.method==='GET'){if(!owner(req))return send(res,401,mime['.json'],JSON.stringify({ok:false,error:'owner_authentication_required'}));return send(res,200,mime['.json'],JSON.stringify({ok:true,content:readContent()}))}
if(u.pathname==='/api/admin/content'&&req.method==='PUT'){if(!owner(req))return send(res,401,mime['.json'],JSON.stringify({ok:false,error:'owner_authentication_required'}));const body=await readBody(req);if(!body||typeof body.content!=='object'||Array.isArray(body.content))return send(res,400,mime['.json'],JSON.stringify({ok:false,error:'content_object_required'}));writeContent(body.content);return send(res,200,mime['.json'],JSON.stringify({ok:true,content:body.content}))}
if(u.pathname==='/api/admin/content/operations'&&req.method==='POST'){if(!owner(req))return send(res,401,mime['.json'],JSON.stringify({ok:false,error:'owner_authentication_required'}));const body=await readBody(req),op=body.operation||{},content=readContent(),collection=String(op.collection||'');if(!Array.isArray(content[collection]))return send(res,400,mime['.json'],JSON.stringify({ok:false,error:'content_collection_required'}));const list=content[collection],type=String(op.type||'');if(type==='add'){const record={...(op.record||{})};if(!record.id)record.id='item-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);list.push(record)}else if(type==='update'){const i=list.findIndex(x=>x.id===op.id);if(i<0)return send(res,404,mime['.json'],JSON.stringify({ok:false,error:'content_record_not_found'}));list[i]={...list[i],...(op.patch||{})}}else if(type==='delete'){const i=list.findIndex(x=>x.id===op.id);if(i<0)return send(res,404,mime['.json'],JSON.stringify({ok:false,error:'content_record_not_found'}));list.splice(i,1)}else if(type==='reorder'&&Array.isArray(op.ids)){const by=new Map(list.map(x=>[x.id,x]));content[collection]=op.ids.map(x=>by.get(x)).filter(Boolean).concat(list.filter(x=>!op.ids.includes(x.id)))}else return send(res,400,mime['.json'],JSON.stringify({ok:false,error:'unsupported_content_operation'}));content.meta={...(content.meta||{}),managed:true,updatedAt:new Date().toISOString()};writeContent(content);return send(res,200,mime['.json'],JSON.stringify({ok:true,content}))}
if(u.pathname==='/robots.txt'){const base=publicBase(req);return send(res,200,'text/plain; charset=utf-8','User-agent: *\\nAllow: /\\nDisallow: /admin\\nDisallow: /api/\\nSitemap: '+base+'/sitemap.xml\\n')}if(u.pathname==='/sitemap.xml'){const base=publicBase(req),pages=spec.pages.filter(p=>!['/admin','/login'].includes(p)),body='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+pages.map(p=>'<url><loc>'+xmlEscape(base+(p||'/'))+'</loc></url>').join('')+'</urlset>';return send(res,200,'application/xml; charset=utf-8',body)}if(!u.pathname.startsWith('/api/')){const staticPath=staticFile(u.pathname);if(staticPath){const body=path.extname(staticPath)==='.html'?renderHtml(staticPath,req,u.pathname):fs.readFileSync(staticPath);return send(res,200,mime[path.extname(staticPath)]||'application/octet-stream',body);}}const api=spec.apis.find(x=>x.path===u.pathname&&String(x.method||'GET').toUpperCase()===String(req.method||'GET').toUpperCase());if(api){const method=String(req.method||'GET').toUpperCase();const key=api.path.split('/').filter(Boolean).pop();const collection=Array.isArray(stores.get(key))?stores.get(key):[];if(method==='GET')return send(res,200,mime['.json'],JSON.stringify({ok:true,path:api.path,method,data:collection.length?collection:(seed.get(key)||seed.get('health')||[])}));const body=await readBody(req);if(method==='POST'){const record={...body,id:body.id||key+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};collection.push(record);stores.set(key,collection);saveStores();return send(res,201,mime['.json'],JSON.stringify({ok:true,path:api.path,method,data:record}));}if(['PUT','PATCH'].includes(method)){const id=String(body.id||body.recordId||'');const index=id?collection.findIndex(x=>String(x.id)===id):-1;if(index<0)return send(res,404,mime['.json'],JSON.stringify({ok:false,error:'record_not_found'}));collection[index]={...collection[index],...body,updatedAt:new Date().toISOString()};stores.set(key,collection);saveStores();return send(res,200,mime['.json'],JSON.stringify({ok:true,path:api.path,method,data:collection[index]}));}if(method==='DELETE'){const id=String(body.id||body.recordId||'');const next=collection.filter(x=>String(x.id)!==id);if(next.length===collection.length)return send(res,404,mime['.json'],JSON.stringify({ok:false,error:'record_not_found'}));stores.set(key,next);saveStores();return send(res,200,mime['.json'],JSON.stringify({ok:true,path:api.path,method,deleted:id}));}return send(res,405,mime['.json'],JSON.stringify({ok:false,error:'method_not_supported'}))}let route=spec.pages.includes(u.pathname)?u.pathname:'/';let file=path.join(publicDir,route==='/'?'index.html':route.slice(1).replace(/[^a-zA-Z0-9_-]/g,'-')+'.html');if(!fs.existsSync(file))file=path.join(publicDir,'index.html');return send(res,200,mime[path.extname(file)]||'text/plain',path.extname(file)==='.html'?renderHtml(file,req,route):fs.readFileSync(file))}catch(e){send(res,500,mime['.json'],JSON.stringify({ok:false,error:e.message}))}}).listen(port,process.env.HOST||'127.0.0.1',()=>console.log(\`build-vibe-preview http://\${process.env.HOST||'127.0.0.1'}:\${port}\`));\n`;}
function acceptance(spec){return `import test from'node:test';import assert from'node:assert/strict';import{spawn}from'node:child_process';import{once}from'node:events';const port=4391;async function wait(){for(let i=0;i<100;i++){try{const r=await fetch(\`http://127.0.0.1:\${port}/api/health\`);if(r.ok)return}catch{}await new Promise(r=>setTimeout(r,50))}throw new Error('preview did not start')}test('generated contract works',async()=>{const child=spawn(process.execPath,['app/server.js'],{env:{...process.env,NODE_TEST_CONTEXT:undefined,HOST:'127.0.0.1',PORT:String(port)},stdio:'ignore'});try{await wait();const routes=${JSON.stringify(spec.pages)};for(const p of routes){const r=await fetch(\`http://127.0.0.1:\${port}\${p}\`);assert.ok(r.status>=200&&r.status<400,\`route \${p}\`)}for(const a of ${JSON.stringify(spec.apis)}){const method=String(a.method||'GET').toUpperCase();const init={method,headers:{'content-type':'application/json'}};if(['POST','PUT','PATCH'].includes(method))init.body=JSON.stringify({test:true});const r=await fetch(\`http://127.0.0.1:\${port}\${a.path}\`,init);const protectedAdmin=String(a.path||'').startsWith('/api/admin/');assert.ok((r.status>=200&&r.status<400)||(protectedAdmin&&(r.status===401||r.status===403)),\`api \${method} \${a.path}\`)}}finally{if(child.exitCode===null){child.kill('SIGTERM');try{await once(child,'exit')}catch{}}}});`}

export function generateProject(spec){
 const files=[];files.push({path:'package.json',content:JSON.stringify({name:'generated-build-vibe-app',version:'0.1.0',private:true,type:'module',scripts:{start:'node app/server.js',test:'node --test test/acceptance.test.js',check:'node --check app/server.js && node --check app/auth.js && node --check public/app.js && node --check public/motion.js && node --check public/content-runtime.js && node --check src/generated/routes.js && node --check src/generated/model.js && node --check public/experience.js'}} ,null,2)+'\n'});
 files.push({path:'codingvibes.app.json',content:JSON.stringify({...spec,generator:`Build Vibe/${CODINGVIBES_VERSION}`},null,2)+'\n'});
 files.push({path:'app/server.js',content:serverJs(spec)});files.push({path:'app/auth.js',content:fs.readFileSync(new URL('../templates/runtime/site-auth.js',import.meta.url),'utf8')});files.push({path:'public/admin.html',content:fs.readFileSync(new URL('../templates/runtime/admin.html',import.meta.url),'utf8')});if(spec.behavior?.publicLogin)files.push({path:'public/login.html',content:fs.readFileSync(new URL('../templates/runtime/login.html',import.meta.url),'utf8')});files.push({path:'.env.example',content:'CV_SESSION_SECRET=generate-a-long-random-secret\nCV_OWNER_EMAIL=owner@example.com\nCV_OWNER_PASSWORD=change-this-immediately\nGOOGLE_CLIENT_ID=\nGOOGLE_CLIENT_SECRET=\nGOOGLE_REDIRECT_URI=http://localhost:4300/auth/google/callback\nCV_GOOGLE_OWNER_EMAILS=owner@example.com\n'});files.push({path:'.gitignore',content:'node_modules/\\n.env\\n.env.*\\n!.env.example\\n.data/\\n.vercel/\\n'});{const runtime=spec.experience?.threeD?fs.readFileSync(new URL('../templates/runtime/three-experience.js',import.meta.url),'utf8'):'export {};';files.push({path:'public/experience.js',content:runtime});}files.push({path:'src/generated/routes.js',content:routesJs(spec)});files.push({path:'src/generated/model.js',content:modelJs(spec)});files.push({path:'public/app.js',content:appJs(spec)});files.push({path:'public/motion.js',content:fs.readFileSync(new URL('../templates/runtime/motion-engine.js',import.meta.url),'utf8')});files.push({path:'public/content-runtime.js',content:contentRuntimeJs()});files.push({path:'public/content/site.json',content:JSON.stringify(createDefaultSiteContent({kind:spec.siteKind||'business',templateId:spec.siteTemplateId||'',templateLabel:spec.siteTemplateLabel||'',request:spec.request}),null,2)+'\n'}); files.push({path:'public/manifest.webmanifest',content:JSON.stringify({name:titleForManifest(spec),short_name:'Build Vibe',start_url:'/',display:'standalone',background_color:'#0b1020',theme_color:'#0b1020',description:String(spec.request||'Build Vibe application').slice(0,200),icons:[{src:'/favicon.svg',sizes:'any',type:'image/svg+xml',purpose:'any maskable'}]},null,2)+'\n'}); files.push({path:'public/llms.txt',content:llmsTxt(spec)});
 files.push({path:'public/favicon.svg',content:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#0b1020"/><path d="M18 21h28v7H36v20h-8V28H18z" fill="#d9f7e2"/><circle cx="48" cy="21" r="4" fill="#7d8dff"/></svg>\n'});
 files.push({path:'public/og-default.svg',content:'<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630"><rect width="1200" height="630" fill="#0b1020"/><circle cx="960" cy="90" r="260" fill="#243b61"/><circle cx="1060" cy="540" r="300" fill="#17243a"/><text x="90" y="230" fill="#8ea8ff" font-family="Arial,Helvetica,sans-serif" font-size="28" font-weight="700" letter-spacing="5">BUILD VIBE</text><text x="90" y="330" fill="#ffffff" font-family="Arial,Helvetica,sans-serif" font-size="76" font-weight="800">Build. Verify. Ship.</text><text x="90" y="390" fill="#aebbd1" font-family="Arial,Helvetica,sans-serif" font-size="30">AI-generated websites and products with structured content and verification.</text></svg>\n'});
 files.push({path:'public/robots.txt',content:'User-agent: *\nAllow: /\nDisallow: /admin\nDisallow: /api/\nSitemap: __SITE_URL__/sitemap.xml\n'});
 files.push({path:'public/sitemap.xml',content:'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+spec.pages.filter(p=>!['/admin','/login'].includes(p)).map(p=>`  <url><loc>__SITE_URL__${p||'/'}</loc></url>\n`).join('')+'</urlset>\n'});
files.push({path:'public/styles.css',content:styles(spec)});
 for(const route of spec.pages){if(route==='/admin'||route==='/login')continue;files.push({path:route==='/'?'public/index.html':`public/${route.slice(1).replace(/[^a-zA-Z0-9_-]/g,'-')}.html`,content:pageMarkup(route,spec)});}
 files.push({path:'test/acceptance.test.js',content:acceptance(spec)});if(spec.target?.id==='web-pwa'){files.push({path:'public/manifest.webmanifest',content:JSON.stringify({name:'Build Vibe app',short_name:'Build Vibe',start_url:'/',display:'standalone',background_color:'#0b1020',theme_color:'#0b1020',icons:[{src:'/favicon.svg',sizes:'any',type:'image/svg+xml',purpose:'any maskable'}]},null,2)+'\n'});files.push({path:'public/sw.js',content:`self.addEventListener('install',()=>self.skipWaiting());self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)));});\n`});}files.push({path:'README.md',content:`# Generated Build Vibe app\n\nThis application was generated from a structured requirements contract and verified before commit.\n\n## Contract\n\n- Pages: ${spec.pages.join(', ')}\n- APIs: ${spec.apis.map(x=>`${x.method} ${x.path}`).join(', ')||'none'}\n- Data entities: ${spec.dataModel.map(x=>x.name).join(', ')||'none'}\n\n## Content architecture\n\nThe visual template reads editable records from public/content/site.json. Products, variants, collections and other site-kit records can be updated without rewriting the presentation layer.\\n\\n## Owner admin\\n\\nEvery generated site includes /admin. Configure CV_OWNER_EMAIL, CV_OWNER_PASSWORD and CV_SESSION_SECRET. A public /login page is generated only when requested.\\n\\n## Deployment\\n\\nThe project is portable. Download the ZIP for compatible cPanel/shared hosting, push the same source to GitHub, or publish the same verified artifact through a configured deployment adapter. Provider credentials are never written into the source tree.\\n`});
 return {files,summary:`Generate ${spec.pages.length} pages and ${spec.apis.length} API routes`,manifestHash:hash(files.map(x=>({path:x.path,content:x.content})))};
}
export function materializeProject(plan,root){for(const file of plan.files){const rel=normalizeRelative(file.path);const target=path.resolve(root,rel);if(!target.startsWith(path.resolve(root)+path.sep))throw new Error('Generated file escapes root');fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,file.content);}}
